// Retail 0x0071A680 assigns the shroud texture handle to the terrain global
// table, then notifies the texture system. The global member offset, handle
// lifetime, and notification call match the W3D shroud family around this body.

class TextureBaseClass
{
public:
	void Release_Ref();
	char m_vptr[4];
	unsigned short m_refs;
};

class ShroudTextureSource
{
public:
	class Handle
	{
	public:
		Handle(const Handle &other)
		{
			m_p = other.m_p;
			if (other.m_p)
				++other.m_p->m_refs;
		}

		~Handle()
		{
			if (m_p)
				m_p->Release_Ref();
		}

		const Handle &operator=(const Handle &other)
		{
			if (other.m_p)
				++other.m_p->m_refs;
			if (m_p)
				m_p->Release_Ref();
			m_p = other.m_p;
			return *this;
		}

		TextureBaseClass *m_p;
	};

	Handle getTexture() const;
};

class Rva0071A680Terrain
{
public:
	char m_pad[0x30B8];
	ShroudTextureSource *m_shroud;
};

extern Rva0071A680Terrain *TheTerrainRenderObject;
